// Read the aggregated task board produced by "Aggregate-Task board list"
const agg = $('Aggregate-Task board list').first().json;
const rows = Array.isArray(agg.sample_task_board) ? agg.sample_task_board : [];

// Find the status field name (case-insensitive), fall back to "Status"
function statusOf(row) {
  const key = Object.keys(row).find(k => k.trim().toLowerCase() === 'status');
  return (key ? row[key] : '').toString().trim();
}

const counts = { 'Done': 0, 'In Progress': 0, 'Blocked': 0, 'To Do': 0 };
const unmatched = [];

for (const row of rows) {
  const raw = statusOf(row);
  const norm = raw.toLowerCase();
  if (norm === 'done') counts['Done']++;
  else if (norm === 'in progress') counts['In Progress']++;
  else if (norm === 'blocked') counts['Blocked']++;
  else if (norm === 'to do' || norm === 'todo') counts['To Do']++;
  else unmatched.push(raw);
}

const total = rows.length;
const sum = counts['Done'] + counts['In Progress'] + counts['Blocked'] + counts['To Do'];

return [{
  json: {
    sample_task_board: rows,          // pass the board through unchanged
    task_counts: counts,              // deterministic counts
    task_total: total,
    task_counts_valid: sum === total, // guard: buckets sum to total
    task_counts_unmatched: unmatched  // any status that didn't map
  }
}];

