const userInput = $('When chat message received').first().json.chatInput ?? '';
const finalOutput = $json.output ?? $json ?? '';

const rawId = ($execution.id + '').replace(/[^a-f0-9]/gi, '').toLowerCase().padEnd(32, '0');
const traceId = rawId.substring(0, 32);

function hex16(seed) {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  const s = h.toString(16).padStart(8, '0');
  return (s + traceId).substring(0, 16);
}

function truncate(v) {
  let str;
  if (v == null) return '';
  try { str = typeof v === 'string' ? v : JSON.stringify(v); } catch (e) { str = String(v); }
  if (str == null) str = '';
  return str.length > 6000 ? str.substring(0, 6000) + '...[truncated]' : str;
}

function safeGet(name) {
  try {
    const items = $(name).all();
    if (!items || !items.length) return null;
    return items.length === 1 ? items[0].json : items.map(function (i) { return i.json; });
  } catch (e) { return null; }
}

const end = Date.now() * 1000000;
const start = end - 5000000000;
const rootSpanId = hex16('MIRA_ROOT');

function makeSpan(name, obsType, input, output, parentId, idx) {
  const attrs = [
    { key: 'langfuse.observation.type', value: { stringValue: obsType } },
    { key: 'langfuse.observation.input', value: { stringValue: truncate(input) } },
    { key: 'langfuse.observation.output', value: { stringValue: truncate(output) } }
  ];
  attrs.push({ key: 'langfuse.trace.name', value: { stringValue: 'MIRA Project Request' } });
  attrs.push({ key: 'langfuse.trace.tags', value: { stringValue: 'Capstone-MIRA' } });
  if (obsType === 'generation') {
    attrs.push({ key: 'gen_ai.request.model', value: { stringValue: 'gpt-4o-mini' } });
  }
  const span = {
    traceId: traceId,
    spanId: parentId ? hex16(name + '_' + idx) : rootSpanId,
    name: name,
    kind: 1,
    startTimeUnixNano: String(start + idx * 1000000),
    endTimeUnixNano: String(end - idx * 500000),
    attributes: attrs
  };
  if (parentId) span.parentSpanId = parentId;
  return span;
}

const spans = [];
spans.push(makeSpan('MIRA Project Request', 'chain', userInput, finalOutput, null, 0));

let idx = 1;
const agents = ['Orchestrator Agent', 'Planner Agent', 'Risk Assessor Agent', 'Status Reporter Agent', 'Milestone Tracker Agent', 'Stakeholder Update Generator Agent'];
for (const a of agents) {
  const data = safeGet(a);
  if (data === null) continue;
  const out = (data && data.output != null) ? data.output : data;
  spans.push(makeSpan(a, 'generation', userInput, out, rootSpanId, idx));
  idx++;
}

const dataNodes = ['Search files and folders', 'Extract from File - Proj desc', 'Extract from File - proj timeline', 'Aggregate-Proj timeline list', 'Router'];
for (const n of dataNodes) {
  const data = safeGet(n);
  if (data === null) continue;
  spans.push(makeSpan(n, 'span', userInput, data, rootSpanId, idx));
  idx++;
}

return {
  json: {
    resourceSpans: [
      {
        resource: {
          attributes: [
            { key: 'service.name', value: { stringValue: 'MIRA-n8n' } }
          ]
        },
        scopeSpans: [
          {
            scope: { name: 'n8n.mira' },
            spans: spans
          }
        ]
      }
    ]
  }
};
